mapper.select:
SELECT v.*, c.customer_type AS customerType
FROM vehicles v
LEFT JOIN customers c ON v.customer_id = c.customer_id


        v.vehicle_id = #{vehicleId}


        AND v.customer_id = #{customerId}


        AND c.customer_type = #{customerType}


        AND (v.license_plate LIKE CONCAT('%', #{searchKey}, '%')
        OR v.vin LIKE CONCAT('%', #{searchKey}, '%')
        OR c.name LIKE CONCAT('%', #{searchKey}, '%'))
